// Uses the stand-in the way Task Proxy's app.js does: it takes window.__TAURI__ and deletes it, runs commands, hears
// events, starts a worker, and moves between pages with pushState, loading each page's markdown from /d/.
const tauri = window.__TAURI__;
delete window.__TAURI__;
const show = (id, text) => { document.getElementById(id).textContent = text; };
document.addEventListener('DOMContentLoaded', async () => {
    show('route', location.pathname);
    show('remote', JSON.stringify(window.__taskProxyRemote));
    tauri.event.listen('run-changed', event => {
        const item = document.createElement('li');
        item.textContent = `${event.event}: ${event.payload.name}`;
        document.getElementById('events').append(item);
    });
    const worker = new Worker('worker.min.js');
    worker.onmessage = event => show('worker', `${event.data}`);
    worker.postMessage(21);
    const loadPage = async () => {
        show('route', location.pathname);
        if (location.pathname === '/') return show('page', '');
        const response = await fetch(`/d${location.pathname}.md`);
        show('page', await response.text());
    };
    document.getElementById('second').addEventListener('click', event => {
        event.preventDefault();
        history.pushState(null, '', '/second');
        loadPage();
    });
    window.addEventListener('popstate', loadPage);
    loadPage();
    show('projects', (await tauri.core.invoke('get_projects')).map(project => project.name).join(', '));
    show('refused', await tauri.core.invoke('desktop_only_command').catch(reason => `${reason}`));
});
